insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Passando em julgado a sentença condenatória, serão os autos de hipoteca ou arresto remetidos ao juiz do cível.', '["Condenação transitada em julgado: autos de hipoteca ou arresto vão ao juízo cível."]'::jsonb, '["Execução da reparação ocorre no cível (art. 63)."]'::jsonb, 'Após o trânsito da condenação, o juízo cível passa a cuidar da hipoteca.', '["Assertiva que mantém os autos de hipoteca no juízo criminal após o trânsito da condenação erra."]'::jsonb, '[]'::jsonb, '["Art. 63"]'::jsonb, 'under_review', 'claude'
