insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Qualquer que seja a decisão sobre o incidente de falsidade, não fará coisa julgada em prejuízo de ulterior processo penal ou civil.', '["A decisão do incidente de falsidade não faz coisa julgada em processo penal ou civil posterior."]'::jsonb, '["Efeito restrito ao processo em que foi proferida."]'::jsonb, 'Reconhecida a falsidade no incidente, o autor ainda pode ser processado, com ampla prova no novo processo.', '["Assertiva que atribui coisa julgada à decisão do incidente de falsidade erra."]'::jsonb, '[]'::jsonb, '["Art. 145"]'::jsonb, 'under_review', 'claude'
