insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando houver dúvida sobre a integridade mental do acusado, o juiz ordenará, de ofício ou a requerimento do Ministério Público, do defensor, do curador, do ascendente, descendente, irmão ou cônjuge do acusado, que seja submetido a exame médico-legal. O exame poderá ser ordenado ainda na fase do inquérito, mediante representação da autoridade policial ao juiz competente. O juiz nomeará curador ao acusado quando determinar o exame, ficando suspenso o processo, se já iniciada a ação penal, salvo quanto às diligências que possam ser prejudicadas pelo adiamento.', '["Dúvida sobre a integridade mental: exame médico-legal.","Determinado de ofício ou a requerimento do MP, defensor, curador ou familiares.","Pode ser ordenado no inquérito, por representação policial.","Juiz nomeia curador e suspende o processo, salvo diligências urgentes."]'::jsonb, '["Instaura-se o incidente de insanidade mental."]'::jsonb, 'Defensor pede exame de sanidade mental do acusado, e o juiz nomeia curador.', '["Assertiva que dispensa curador no incidente de insanidade mental erra."]'::jsonb, '[{"termo":"Incidente de insanidade mental","significado":"Procedimento para avaliar a integridade mental do acusado."}]'::jsonb, '["Art. 150","Art. 152"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-149'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para o efeito do exame, o acusado, se estiver preso, será internado em manicômio judiciário, onde houver, ou, se estiver solto e o requererem os peritos, em estabelecimento adequado que o juiz designar. O exame não durará mais de quarenta e cinco dias, salvo se os peritos demonstrarem a necessidade de maior prazo. Se não houver prejuízo para a marcha do processo, o juiz pode autorizar que os autos sejam entregues aos peritos.', '["Acusado preso: internado em manicômio judiciário, se houver.","Acusado solto: estabelecimento adequado, se os peritos requererem.","Exame em até quarenta e cinco dias, prorrogável se demonstrada a necessidade.","Autos podem ser entregues aos peritos."]'::jsonb, '["Prazo do exame: quarenta e cinco dias."]'::jsonb, 'Perito pede mais tempo para concluir o exame de sanidade, demonstrando a necessidade.', '["Assertiva que fixa em trinta dias o prazo do exame de insanidade erra: são quarenta e cinco dias."]'::jsonb, '[]'::jsonb, '["Art. 149"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-150'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se os peritos concluírem que o acusado era, ao tempo da infração, irresponsável nos termos do art. 22 do Código Penal, o processo prosseguirá com a presença do curador.', '["Irresponsabilidade ao tempo da infração: processo prossegue.","Presença do curador."]'::jsonb, '["Possível absolvição imprópria com medida de segurança."]'::jsonb, 'Perícia conclui que o acusado era inimputável ao tempo do fato, e o processo continua com curador.', '["Assertiva que extingue o processo com a conclusão pericial de inimputabilidade erra."]'::jsonb, '[]'::jsonb, '["Art. 149","Art. 152"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-151'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se se verificar que a doença mental sobreveio à infração, o processo continuará suspenso até que o acusado se restabeleça, observado o §2º do art. 149. O juiz poderá ordenar a internação do acusado em manicômio judiciário ou outro estabelecimento adequado. O processo retomará seu curso desde que o acusado se restabeleça, ficando-lhe assegurada a faculdade de reinquirir as testemunhas que houverem prestado depoimento sem a sua presença.', '["Doença mental superveniente à infração: processo suspenso até o restabelecimento.","Internação possível.","Retomada do processo: o acusado pode reinquirir testemunhas ouvidas na sua ausência."]'::jsonb, '["Doença posterior à infração suspende o processo; anterior, o processo segue com curador."]'::jsonb, 'Acusado adoece mentalmente durante o processo, que fica suspenso até o restabelecimento.', '["Assertiva que prossegue o processo normalmente com doença mental superveniente erra: fica suspenso."]'::jsonb, '[]'::jsonb, '["Art. 149","Art. 151"]'::jsonb, 'under_review', 'claude'
