insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O incidente da insanidade mental processar-se-á em autos apartados, que só depois da apresentação do laudo serão apensados ao processo principal.', '["Incidente em autos apartados.","Apensação ao principal somente após o laudo."]'::jsonb, '["Autos apartados até o laudo."]'::jsonb, 'O incidente de sanidade corre em apenso e é juntado ao principal só com o laudo.', '["Assertiva que determina que o incidente tramite nos próprios autos do processo principal erra."]'::jsonb, '[]'::jsonb, '["Art. 149"]'::jsonb, 'under_review', 'claude'
