select u.id, u.content_sha256, 'Se a insanidade mental sobrevier no curso da execução da pena, observar-se-á o disposto no art. 682.', '["Insanidade superveniente na execução da pena segue o art. 682."]'::jsonb, '["Remissão ao Livro da execução."]'::jsonb, 'Condenado apresenta insanidade durante o cumprimento da pena: aplica-se o art. 682.', '["Assertiva que aplica o incidente dos arts. 149 a 153 à execução da pena erra: aplica-se o art. 682."]'::jsonb, '[]'::jsonb, '["Art. 682"]'::jsonb, 'under_review', 'claude'
