insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A autoridade e as partes poderão formular quesitos até o ato da diligência.', '["Quesitos podem ser formulados até o ato da diligência."]'::jsonb, '["Prazo: até a realização do ato."]'::jsonb, 'A defesa apresenta quesitos antes do início da perícia.', '["Assertiva que veda a formulação de quesitos pela autoridade erra."]'::jsonb, '[{"termo":"Quesitos","significado":"Perguntas dirigidas aos peritos."}]'::jsonb, '["Art. 159"]'::jsonb, 'under_review', 'claude'
