insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No exame por precatória, a nomeação dos peritos far-se-á no juízo deprecado. Havendo, porém, no caso de ação privada, acordo das partes, essa nomeação poderá ser feita pelo juiz deprecante. Os quesitos do juiz e das partes serão transcritos na precatória.', '["Exame por precatória: peritos nomeados no juízo deprecado.","Ação privada: acordo das partes permite nomeação pelo juiz deprecante.","Quesitos transcritos na precatória."]'::jsonb, '["Regra: juízo deprecado nomeia."]'::jsonb, 'Perícia em outra comarca: o juízo deprecado nomeia o perito.', '["Assertiva que sempre atribui ao juízo deprecante a nomeação dos peritos erra."]'::jsonb, '[]'::jsonb, '["Art. 159"]'::jsonb, 'under_review', 'claude'
