insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No caso do art. 159, o exame será requisitado pela autoridade ao diretor da repartição, juntando-se ao processo o laudo assinado pelos peritos.', '["Exame requisitado pela autoridade ao diretor da repartição.","Laudo assinado pelos peritos é juntado ao processo."]'::jsonb, '["Perícia oficial é requisitada à repartição."]'::jsonb, 'O delegado requisita o exame ao diretor do instituto de criminalística.', '["Assertiva que dispensa a assinatura dos peritos no laudo erra."]'::jsonb, '[]'::jsonb, '["Art. 159"]'::jsonb, 'under_review', 'claude'
