insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se houver divergência entre os peritos, serão consignadas no auto do exame as declarações e respostas de um e de outro, ou cada um redigirá separadamente o seu laudo, e a autoridade nomeará um terceiro; se este divergir de ambos, a autoridade poderá mandar proceder a novo exame por outros peritos.', '["Divergência: consignam-se as respostas de cada perito, ou laudos separados.","A autoridade nomeia um terceiro perito.","Se o terceiro divergir de ambos, novo exame por outros peritos."]'::jsonb, '["Terceiro perito resolve a divergência."]'::jsonb, 'Dois peritos divergem, e a autoridade nomeia um terceiro.', '["Assertiva que determina o descarte do laudo em caso de divergência entre peritos erra."]'::jsonb, '[]'::jsonb, '["Art. 159"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-180'
