insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No caso de inobservância de formalidades, ou no caso de omissões, obscuridades ou contradições, a autoridade judiciária mandará suprir a formalidade, complementar ou esclarecer o laudo. A autoridade poderá também ordenar que se proceda a novo exame, por outros peritos, se julgar conveniente.', '["Falhas do laudo: a autoridade manda suprir, complementar ou esclarecer.","Pode ordenar novo exame por outros peritos."]'::jsonb, '["Poder da autoridade para sanar o laudo."]'::jsonb, 'Juiz manda o perito esclarecer uma contradição no laudo.', '["Assertiva que impede o juiz de determinar novo exame por outros peritos erra."]'::jsonb, '[]'::jsonb, '["Art. 180","Art. 182"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-181'
