select u.id, u.content_sha256, 'Nos crimes em que não couber ação pública, observar-se-á o disposto no art. 19.', '["Ação privada: aplica-se o art. 19 (autos entregues ao ofendido ou aguardam sua iniciativa)."]'::jsonb, '["Remissão ao art. 19."]'::jsonb, 'Em crime de ação privada, os autos periciais seguem o destino do art. 19.', '["Assertiva que aplica o art. 183 à ação penal pública erra."]'::jsonb, '[]'::jsonb, '["Art. 19"]'::jsonb, 'under_review', 'claude'
