insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Salvo o caso de exame de corpo de delito, o juiz ou a autoridade policial negará a perícia requerida pelas partes quando não for necessária ao esclarecimento da verdade.', '["Perícia requerida pelas partes pode ser negada se desnecessária.","Exceção: exame de corpo de delito não pode ser negado."]'::jsonb, '["Exame de corpo de delito é obrigatório quando há vestígios."]'::jsonb, 'A autoridade nega uma perícia desnecessária requerida pela defesa.', '["Assertiva que permite negar o exame de corpo de delito por desnecessário erra."]'::jsonb, '[]'::jsonb, '["Art. 158"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-184'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O acusado que comparecer perante a autoridade judiciária, no curso do processo penal, será qualificado e interrogado na presença de seu defensor, constituído ou nomeado. O interrogatório do réu preso será realizado em sala própria, no estabelecimento em que estiver recolhido, desde que garantidas a segurança do juiz, do membro do Ministério Público e dos auxiliares, a presença do defensor e a publicidade do ato. Excepcionalmente, o juiz, por decisão fundamentada, de ofício ou a requerimento das partes, pode realizar o interrogatório do réu preso por videoconferência ou outro recurso tecnológico de transmissão de sons e imagens em tempo real, desde que necessário para prevenir risco à segurança pública (suspeita de integrar organização criminosa ou de fuga durante o deslocamento), viabilizar a participação do réu quando haja relevante dificuldade para comparecer em juízo, impedir a influência do réu no ânimo de testemunha ou da vítima, ou responder a gravíssima questão de ordem pública, conforme as hipóteses do dispositivo.', '["Interrogatório na presença do defensor, constituído ou nomeado.","Réu preso: sala própria do estabelecimento, com segurança, defensor e publicidade.","Videoconferência: excepcional, por decisão fundamentada, em hipóteses legais.","Hipóteses: risco à segurança pública, dificuldade de comparecimento, influência sobre testemunha ou vítima, questão de ordem pública."]'::jsonb, '["Videoconferência é EXCEÇÃO e exige decisão fundamentada.","A presença do defensor é obrigatória."]'::jsonb, 'Réu preso com suspeita de integrar organização criminosa é interrogado por videoconferência, por decisão fundamentada.', '["Assertiva que torna a videoconferência a regra para o interrogatório do réu preso erra: é excepcional."]'::jsonb, '[]'::jsonb, '["Art. 186","Art. 187"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-185'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Depois de devidamente qualificado e cientificado do inteiro teor da acusação, o acusado será informado pelo juiz, antes de iniciar o interrogatório, do seu direito de permanecer calado e de não responder perguntas que lhe forem formuladas. O silêncio, que não importará em confissão, não poderá ser interpretado em prejuízo da defesa.', '["Qualificação e ciência da acusação antes do interrogatório.","Juiz informa o direito de permanecer calado.","O silêncio não é confissão e não prejudica a defesa."]'::jsonb, '["Direito ao silêncio: nemo tenetur se detegere.","O art. 198 trazia redação anterior de que o silêncio poderia ser elemento de convencimento; hoje prevalece o art. 186."]'::jsonb, 'Antes do interrogatório, o juiz avisa que o acusado pode ficar em silêncio.', '["Assertiva que interpreta o silêncio em prejuízo da defesa erra."]'::jsonb, '[{"termo":"Direito ao silêncio","significado":"Ninguém é obrigado a produzir prova contra si."}]'::jsonb, '["Art. 198"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-186'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O interrogatório será constituído de duas partes: sobre a pessoa do acusado e sobre os fatos. Na primeira parte, o interrogando será perguntado sobre residência, meios de vida ou profissão, oportunidades sociais, lugar onde exerce sua atividade, vida pregressa (se foi preso ou processado, juízo, suspensão condicional ou condenação, pena imposta e cumprimento) e outros dados familiares e sociais. Na segunda parte será perguntado sobre ser verdadeira a acusação; se não, o motivo particular a que atribuí-la, se conhece a pessoa a quem deva ser imputada e se com ela esteve; onde estava ao tempo da infração e se teve notícia; as provas já apuradas; se conhece as vítimas e testemunhas; e todos os demais fatos e pormenores que conduzam à elucidação dos antecedentes e circunstâncias da infração.', '["Duas partes: sobre a pessoa e sobre os fatos.","Primeira parte: residência, profissão, vida pregressa, dados familiares e sociais.","Segunda parte: veracidade da acusação, álibi, provas apuradas, vítimas e testemunhas, circunstâncias."]'::jsonb, '["Estrutura em duas partes."]'::jsonb, 'O juiz pergunta primeiro sobre a pessoa do acusado e depois sobre os fatos.', '["Assertiva que divide o interrogatório em três partes erra: são duas."]'::jsonb, '[]'::jsonb, '["Art. 186","Art. 188"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-187'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Após proceder ao interrogatório, o juiz indagará das partes se restou algum fato para ser esclarecido, formulando as perguntas correspondentes se o entender pertinente e relevante.', '["Após o interrogatório, o juiz pergunta às partes se resta fato a esclarecer.","Formula perguntas pertinentes e relevantes."]'::jsonb, '["As partes não perguntam diretamente: pedem ao juiz."]'::jsonb, 'A defesa sugere pergunta ao juiz, que a formula ao acusado.', '["Assertiva que permite às partes perguntar diretamente ao acusado, nos termos do art. 188, erra: o juiz formula as perguntas."]'::jsonb, '[]'::jsonb, '["Art. 187"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-188'
