insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se confessar a autoria, o acusado será perguntado sobre os motivos e circunstâncias do fato e se outras pessoas concorreram para a infração, e quais sejam.', '["Confissão: perguntas sobre motivos e circunstâncias.","Perguntas sobre concurso de outras pessoas."]'::jsonb, '["Explora a confissão para identificar coautores."]'::jsonb, 'Ao confessar, o acusado informa quem o ajudou.', '["Assertiva que dispensa perguntas sobre motivos e circunstâncias na confissão erra."]'::jsonb, '[]'::jsonb, '["Art. 189"]'::jsonb, 'under_review', 'claude'
