select u.id, u.content_sha256, 'Havendo mais de um acusado no processo, cada um será interrogado separadamente, sem presença dos demais corréus.', '["Interrogatório separado de cada acusado."]'::jsonb, '["Evita a interferência entre os depoimentos."]'::jsonb, 'Dois corréus são interrogados um de cada vez.', '["Assertiva que determina o interrogatório conjunto de todos os acusados erra."]'::jsonb, '[]'::jsonb, '["Art. 185"]'::jsonb, 'under_review', 'claude'
