insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O interrogatório do mudo, do surdo ou do surdo-mudo será feito assim: ao surdo, as perguntas por escrito e a resposta oral; ao mudo, as perguntas orais e a resposta escrita; ao surdo-mudo, perguntas e respostas por escrito. Caso o interrogando não saiba ler ou escrever, intervirá no ato, como intérprete e sob compromisso, pessoa habilitada a entendê-lo.', '["Surdo: perguntas escritas, respostas orais.","Mudo: perguntas orais, respostas escritas.","Surdo-mudo: perguntas e respostas escritas.","Analfabeto: intérprete sob compromisso."]'::jsonb, '["Terminologia antiga; hoje usa-se intérprete de Libras (Lei nº 13.146, de 2015)."]'::jsonb, 'Ao surdo, o juiz apresenta as perguntas por escrito, e ele responde oralmente.', '["Assertiva que inverte as formas de comunicação do surdo e do mudo erra."]'::jsonb, '[]'::jsonb, '["Art. 193"]'::jsonb, 'under_review', 'claude'
