insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A todo tempo o juiz poderá proceder a novo interrogatório de ofício ou a pedido fundamentado de qualquer das partes.', '["Novo interrogatório a qualquer tempo.","De ofício ou a pedido fundamentado das partes."]'::jsonb, '["Pedido deve ser fundamentado."]'::jsonb, 'Surgida nova prova, o juiz determina novo interrogatório.', '["Assertiva que veda novo interrogatório após o primeiro erra."]'::jsonb, '[]'::jsonb, '["Art. 185"]'::jsonb, 'under_review', 'claude'
