insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O depoimento será prestado oralmente, não sendo permitido à testemunha trazê-lo por escrito. Não será vedada à testemunha, entretanto, breve consulta a apontamentos.', '["Depoimento oral.","Vedado trazê-lo por escrito.","Breve consulta a apontamentos é permitida."]'::jsonb, '["Oralidade com breve consulta."]'::jsonb, 'A testemunha consulta rapidamente uma anotação com datas.', '["Assertiva que permite à testemunha depor lendo texto escrito erra."]'::jsonb, '[]'::jsonb, '["Art. 203"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-204'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se ocorrer dúvida sobre a identidade da testemunha, o juiz procederá à verificação pelos meios ao seu alcance, podendo, entretanto, tomar-lhe o depoimento desde logo.', '["Dúvida sobre a identidade: o juiz verifica pelos meios ao seu alcance.","Pode tomar o depoimento desde logo."]'::jsonb, '["Não impede o depoimento imediato."]'::jsonb, 'Juiz colhe o depoimento enquanto confirma a identidade da testemunha.', '["Assertiva que impede o depoimento até a confirmação da identidade erra."]'::jsonb, '[]'::jsonb, '["Art. 203"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-205'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A testemunha não poderá eximir-se da obrigação de depor. Poderão, entretanto, recusar-se a fazê-lo o ascendente ou descendente, o afim em linha reta, o cônjuge (ainda que desquitado), o irmão e o pai, a mãe ou o filho adotivo do acusado, salvo quando não for possível, por outro modo, obter-se ou integrar-se a prova do fato e de suas circunstâncias.', '["Regra: dever de depor.","Podem recusar-se: ascendente, descendente, afim em linha reta, cônjuge, irmão, pais ou filho adotivo do acusado.","Exceção: quando não for possível obter a prova de outro modo."]'::jsonb, '["Os parentes podem recusar-se, mas, se não houver outro meio de prova, devem depor (sem compromisso)."]'::jsonb, 'Irmão do acusado pode se recusar a depor, salvo se não houver outro modo de provar o fato.', '["Assertiva que obriga o cônjuge do acusado a depor em qualquer hipótese erra: ele pode se recusar, salvo quando a prova não puder ser obtida por outro modo."]'::jsonb, '[]'::jsonb, '["Art. 208"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-206'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São proibidas de depor as pessoas que, em razão de função, ministério, ofício ou profissão, devam guardar segredo, salvo se, desobrigadas pela parte interessada, quiserem dar o seu testemunho.', '["Proibição de depor para quem tem dever de sigilo profissional.","Exceção: desobrigadas pela parte interessada e dispostas a depor."]'::jsonb, '["Sigilo profissional (advogado, médico, sacerdote etc.).","Mesmo desobrigada, a pessoa só depõe se QUISER."]'::jsonb, 'Advogado não pode depor sobre segredo de seu cliente, salvo desobrigado por este e querendo depor.', '["Assertiva que obriga a pessoa desobrigada pela parte a depor erra: ela depõe se quiser."]'::jsonb, '[]'::jsonb, '["Art. 214"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-207'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não se deferirá o compromisso a que alude o art. 203 aos doentes e deficientes mentais e aos menores de 14 anos, nem às pessoas a que se refere o art. 206.', '["Sem compromisso: doentes e deficientes mentais, menores de 14 anos e parentes do art. 206."]'::jsonb, '["Quem depõe sem compromisso não comete falso testemunho."]'::jsonb, 'Criança de 10 anos depõe sem prestar compromisso.', '["Assertiva que exige compromisso do menor de 14 anos erra."]'::jsonb, '[{"termo":"Informante","significado":"Quem depõe sem compromisso de dizer a verdade."}]'::jsonb, '["Art. 203","Art. 206"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-208'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz, quando julgar necessário, poderá ouvir outras testemunhas, além das indicadas pelas partes. Se ao juiz parecer conveniente, serão ouvidas as pessoas a que as testemunhas se referirem. Não será computada como testemunha a pessoa que nada souber que interesse à decisão da causa.', '["Juiz pode ouvir outras testemunhas além das indicadas.","Pessoas mencionadas pelas testemunhas podem ser ouvidas.","Quem nada sabe de interesse não é computada como testemunha."]'::jsonb, '["Testemunhas do juízo e referidas."]'::jsonb, 'Juiz ouve pessoa referida por uma testemunha como conhecedora do fato.', '["Assertiva que restringe a oitiva às testemunhas indicadas pelas partes erra."]'::jsonb, '[{"termo":"Testemunha referida","significado":"Pessoa mencionada no depoimento de outra testemunha."}]'::jsonb, '["Art. 202"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-209'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As testemunhas serão inquiridas cada uma de per si, de modo que umas não saibam nem ouçam os depoimentos das outras, devendo o juiz adverti-las das penas cominadas ao falso testemunho. Antes do início da audiência e durante a sua realização, serão reservados espaços separados para a garantia da incomunicabilidade das testemunhas.', '["Inquirição individual e incomunicável.","Juiz adverte sobre as penas do falso testemunho.","Espaços separados antes e durante a audiência."]'::jsonb, '["Incomunicabilidade das testemunhas."]'::jsonb, 'Testemunhas aguardam em salas separadas até serem chamadas.', '["Assertiva que permite que uma testemunha ouça o depoimento da outra erra."]'::jsonb, '[]'::jsonb, '["Art. 211"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-210'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se o juiz, ao pronunciar sentença final, reconhecer que alguma testemunha fez afirmação falsa, calou ou negou a verdade, remeterá cópia do depoimento à autoridade policial para a instauração de inquérito. Tendo o depoimento sido prestado em plenário de julgamento, o juiz, o tribunal ou o conselho de sentença, após a votação dos quesitos, poderão fazer apresentar imediatamente a testemunha à autoridade policial.', '["Falso testemunho reconhecido na sentença: cópia do depoimento à autoridade policial.","Depoimento em plenário: a testemunha pode ser apresentada de imediato à autoridade policial."]'::jsonb, '["Apresentação imediata no plenário do Júri."]'::jsonb, 'Após a sentença, o juiz envia à polícia cópia do depoimento falso para investigar.', '["Assertiva que determina que o próprio juiz instaure inquérito nesses casos erra: remete cópia à autoridade policial."]'::jsonb, '[]'::jsonb, '["Art. 342 do Código Penal"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-211'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As perguntas serão formuladas pelas partes diretamente à testemunha, não admitindo o juiz aquelas que puderem induzir a resposta, não tiverem relação com a causa ou importarem na repetição de outra já respondida. Sobre os pontos não esclarecidos, o juiz poderá complementar a inquirição.', '["Perguntas feitas diretamente pelas partes à testemunha (sistema presidencialista abandonado).","Indeferidas as que induzem a resposta, sem relação com a causa ou repetitivas.","Juiz complementa a inquirição."]'::jsonb, '["Sistema do exame direto (cross examination): partes perguntam diretamente.","Juiz complementa, e não inicia a inquirição."]'::jsonb, 'A defesa pergunta diretamente à testemunha, e o juiz indefere pergunta indutiva.', '["Assertiva que determina que as partes perguntem por intermédio do juiz erra: perguntam diretamente."]'::jsonb, '[]'::jsonb, '["Art. 188"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-212'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

